WITH RECURSIVE d(i) AS (VALUES(1) UNION ALL SELECT i+4 FROM d WHERE i+4<=200) DELETE FROM table1 WHERE f1 IN (SELECT i FROM d); DELETE FROM table1 WHERE f1>50; WITH RECURSIVE d(i) AS (VALUES(1) UNION ALL SELECT i+3 FROM d WHERE i+3<=70) DELETE FROM table1 WHERE f1 IN (SELECT i FROM d); DELETE FROM table1 WHERE f1>=1 AND f1<40; DELETE FROM table1 WHERE f1!=48;